import{_ as l,a0 as o,w as r,s as g,ao as p,I as n,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"GoAccess：一个实时的 Web 日志分析器及交互式查看器 | LCTT x X-CMD","titleTemplate":false,"description":"GoAccess：一个实时的 Web 日志分析器及交互式查看器 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GoAccess：一个实时的 Web 日志分析器及交互式查看器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GoAccess：一个实时的 Web 日志分析器及交互式查看器 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer","title":"GoAccess：一个实时的 Web 日志分析器及交互式查看器","tag":"201906","desc":""},"relativePath":"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer.md","filePath":"[post].md"}'),c={name:"201906/20190109 GoAccess - A Real-Time Web Server Log Analyzer And Interactive Viewer.md"};function d(h,s,k,u,b,m){const a=o("Link");return r(),g("div",null,[s[32]||(s[32]=p('<h1 id="goaccess-一个实时的-web-日志分析器及交互式查看器" tabindex="-1">GoAccess：一个实时的 Web 日志分析器及交互式查看器 <a class="header-anchor" href="#goaccess-一个实时的-web-日志分析器及交互式查看器" aria-label="Permalink to “GoAccess：一个实时的 Web 日志分析器及交互式查看器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201906/12/222616h80pl0k0tt811071.jpg" alt=""></p><p>分析日志文件对于 Linux 管理员来说是一件非常令人头疼的事情，因为它记录了很多东西。大多数新手和初级管理员都不知道如何分析。如果你在分析日志方面拥有很多知识，那么你就成了 *NIX 系统高手。</p><p>Linux 中有许多工具可以轻松分析日志。GoAccess 是允许用户轻松分析 Web 服务器日志的工具之一。我们将在本文中详细讨论 GoAccess 工具。</p><h3 id="goaccess" tabindex="-1">GoAccess <a class="header-anchor" href="#goaccess" aria-label="Permalink to “GoAccess”">​</a></h3><p>GoAccess 是一个实时 Web 日志分析器和交互式查看器，可以在 *nix 系统中的终端运行或通过浏览器访问。</p><p>GoAccess 需要的依赖极少，它是用 C 语言编写的，只需要 ncurses。</p><p>它支持 Apache、Nginx 和 Lighttpd 日志。它为需要动态可视化服务器报告的系统管理员即时提供了快速且有价值的 HTTP 统计信息。</p><p>GoAccess 可以解析指定的 Web 日志文件并将数据输出到 X 终端和浏览器。</p><p>GoAccess 被设计成一个基于终端的快速日志分析器。其核心思想是实时快速分析和查看 Web 服务器统计信息，而无需使用浏览器。</p><p>默认输出是在终端输出，它也能够生成完整的、自包含的实时 HTML 报告，以及 JSON 和 CSV 报告。</p><p>GoAccess 支持任何自定义日志格式，并包含以下预定义日志格式选项：Apache/Nginx 中的组合日志格式 XLF/ELF，Apache 中的通用日志格式 CLF，但不限于此。</p><h3 id="goaccess-功能" tabindex="-1">GoAccess 功能 <a class="header-anchor" href="#goaccess-功能" aria-label="Permalink to “GoAccess 功能”">​</a></h3><ul><li>完全实时：所有指标在终端上每 200 毫秒更新一次，在 HTML 输出上每秒更新一次。</li><li>跟踪应用程序响应时间：跟踪服务请求所需的时间。如果你想跟踪减慢了网站速度的网页，则非常有用。</li><li>访问者：按小时或日期确定最慢运行的请求的点击量、访问者数、带宽数和指标。</li><li>按虚拟主机的度量标准：如果有多个虚拟主机（<code>Server</code>），它提供了一个面板，可显示哪些虚拟主机正在消耗大部分 Web 服务器资源。</li></ul><h3 id="如何安装-goaccess" tabindex="-1">如何安装 GoAccess？ <a class="header-anchor" href="#如何安装-goaccess" aria-label="Permalink to “如何安装 GoAccess？”">​</a></h3><p>我建议用户在包管理器的帮助下从发行版官方的存储库安装 GoAccess。它在大多数发行版官方存储库中都可用。</p><p>我们知道，我们在标准发行方式的发行版中得到的是过时的软件包，而滚动发行方式的发行版总是包含最新的软件包。</p><p>如果你使用标准发行方式的发行版运行操作系统，我建议你检查替代选项，如 PPA 或 GoAccess 官方维护者存储库等，以获取最新的软件包。</p>',18)),n("p",null,[s[2]||(s[2]=e("对于 Debian / Ubuntu 系统，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-get-apt-cache-command-examples-manage-packages-debian-ubuntu-systems/"},{default:t(()=>[...s[0]||(s[0]=[e("APT-GET 命令",-1)])]),_:1}),s[3]||(s[3]=e("或 ",-1)),i(a,{href:"https://www.2daygeek.com/apt-command-examples-manage-packages-debian-ubuntu-systems/"},{default:t(()=>[...s[1]||(s[1]=[e("APT 命令",-1)])]),_:1}),s[4]||(s[4]=e("在你的系统上安装 GoAccess。",-1))]),s[33]||(s[33]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install goaccess</span></span></code></pre></div><p>要获取最新的 GoAccess 包，请使用以下 GoAccess 官方存储库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;deb https://deb.goaccess.io/ $(lsb_release -cs) main&quot; | sudo tee -a /etc/apt/sources.list.d/goaccess.list</span></span>
<span class="line"><span>$ wget -O - https://deb.goaccess.io/gnugpg.key | sudo apt-key add -</span></span>
<span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install goaccess</span></span></code></pre></div>`,3)),n("p",null,[s[6]||(s[6]=e("对于 RHEL / CentOS 系统，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/yum-command-examples-manage-packages-rhel-centos-systems/"},{default:t(()=>[...s[5]||(s[5]=[e("YUM 包管理器",-1)])]),_:1}),s[7]||(s[7]=e("在你的系统上安装 GoAccess。",-1))]),s[34]||(s[34]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install goaccess</span></span></code></pre></div>',1)),n("p",null,[s[9]||(s[9]=e("对于 Fedora 系统，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/dnf-command-examples-manage-packages-fedora-system/"},{default:t(()=>[...s[8]||(s[8]=[e("DNF 包管理器",-1)])]),_:1}),s[10]||(s[10]=e("在你的系统上安装 GoAccess。",-1))]),s[35]||(s[35]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install goaccess</span></span></code></pre></div>',1)),n("p",null,[s[12]||(s[12]=e("对于基于 ArchLinux / Manjaro 的系统，使用 ",-1)),i(a,{href:"https://www.2daygeek.com/pacman-command-examples-manage-packages-arch-linux-system/"},{default:t(()=>[...s[11]||(s[11]=[e("Pacman 包管理器",-1)])]),_:1}),s[13]||(s[13]=e("在你的系统上安装 GoAccess。",-1))]),s[36]||(s[36]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S goaccess</span></span></code></pre></div>',1)),n("p",null,[s[15]||(s[15]=e("对于 openSUSE Leap 系统，使用",-1)),i(a,{href:"https://www.2daygeek.com/zypper-command-examples-manage-packages-opensuse-system/"},{default:t(()=>[...s[14]||(s[14]=[e("Zypper 包管理器",-1)])]),_:1}),s[16]||(s[16]=e("在你的系统上安装 GoAccess。",-1))]),s[37]||(s[37]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># zypper install goaccess</span></span>
<span class="line"><span># zypper ar -f obs://server:http</span></span>
<span class="line"><span># zypper ref &amp;&amp; zypper in goaccess</span></span></code></pre></div><h3 id="如何使用-goaccess" tabindex="-1">如何使用 GoAccess？ <a class="header-anchor" href="#如何使用-goaccess" aria-label="Permalink to “如何使用 GoAccess？”">​</a></h3><p>成功安装 GoAccess 后。只需输入 <code>goaccess</code> 命令，然后输入 Web 服务器日志位置即可查看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess [options] /path/to/Web Server/access.log</span></span>
<span class="line"><span># goaccess /var/log/apache/2daygeek_access.log</span></span></code></pre></div><p>执行上述命令时，它会要求您选择日志格式配置。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-1.png" alt=""></p><p>我用 Apache 访问日志对此进行了测试。Apache 日志被分为十五个部分。详情如下。主要部分显示了这十五个部分的摘要。</p><p>以下屏幕截图包括四个部分，例如唯一身份访问者、请求的文件、静态请求、未找到的网址。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-3.png" alt=""></p><p>以下屏幕截图包括四个部分，例如访客主机名和 IP、操作系统、浏览器、时间分布。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-3.png" alt=""></p><p>以下屏幕截图包括四个部分，例如来源网址、来源网站，Google 的搜索引擎结果、HTTP状态代码。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-4.png" alt=""></p><p>如果要生成 html 报告，请使用以下命令。最初我在尝试生成 html 报告时遇到错误。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess 2daygeek_access.log -a &gt; report.html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GoAccess - version 1.3 - Nov 23 2018 11:28:19</span></span>
<span class="line"><span>Config file: No config file used</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fatal error has occurred</span></span>
<span class="line"><span>Error occurred at: src/parser.c - parse_log - 2764</span></span>
<span class="line"><span>No time format was found on your conf file.Parsing... [0] [0/s]</span></span></code></pre></div><p>它说“你的 conf 文件没有找到时间格式”。要解决此问题，请为其添加 “COMBINED” 日志格式选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># goaccess -f 2daygeek_access.log --log-format=COMBINED -o 2daygeek.html</span></span>
<span class="line"><span>Parsing...[0,165] [50,165/s]</span></span></code></pre></div><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/01/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer-5.png" alt=""></p><p>GoAccess 也允许你访问和分析实时日志并进行过滤和解析。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/apache/2daygeek_access.log | goaccess -</span></span></code></pre></div><p>更多细节请参考其 man 手册页或帮助。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># man goaccess</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># goaccess --help</span></span></code></pre></div><hr>`,23)),n("p",null,[s[18]||(s[18]=e("via: ",-1)),i(a,{href:"https://www.2daygeek.com/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer/"},{default:t(()=>[...s[17]||(s[17]=[e("https://www.2daygeek.com/goaccess-a-real-time-web-server-log-analyzer-and-interactive-viewer/",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("作者：",-1)),i(a,{href:"https://www.2daygeek.com/author/vinoth/"},{default:t(()=>[...s[19]||(s[19]=[e("Vinoth Kumar",-1)])]),_:1}),s[24]||(s[24]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[20]||(s[20]=[e("lujun9972",-1)])]),_:1}),s[25]||(s[25]=e(" 译者：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[e("wxy",-1)])]),_:1}),s[26]||(s[26]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[22]||(s[22]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[29]||(s[29]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[27]||(s[27]=[e("LCTT",-1)])]),_:1}),s[30]||(s[30]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[28]||(s[28]=[e("Linux中国",-1)])]),_:1}),s[31]||(s[31]=e(" 荣誉推出",-1))])])}const w=l(c,[["render",d]]);export{A as __pageData,w as default};
